panels.code:
.card {
  width: 200px;
  padding: 20px;
  border: 5px solid;
}
/* content-box: 200 + 40 + 10 = 250px */

* { box-sizing: border-box; }
/* border-box: total stays 200px */

.nav {
  display: flex;
  justify-content: space-between;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
